function toDate(val) {
  if (!val) return '';
  if (typeof val === 'number') {
    const d = new Date(Date.UTC(1899, 11, 30) + val * 86400000);
    return String(d.getUTCDate()).padStart(2,'0') + '/' + String(d.getUTCMonth()+1).padStart(2,'0') + '/' + d.getUTCFullYear();
  }
  if (typeof val === 'string' && val.includes('/')) return val;
  if (typeof val === 'string') {
    const d = new Date(val);
    if (!isNaN(d.getTime())) return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear();
  }
  return String(val);
}

const configRows   = $('Ler config').all().map(i => i.json).filter(r => r.chave);
const atletasRows  = $('Ler atletas').all().map(i => i.json).filter(r => r.Camisa);
const rifasRows    = $('Ler rifas_avulsas').all().map(i => i.json).filter(r => r.id && r.total_arrecadado);
const cantinaRows  = $('Ler cantina').all().map(i => i.json).filter(r => r.id && r.total_arrecadado);
const doacoesRows  = $('Ler doacoes').all().map(i => i.json).filter(r => r.id && r.valor);
const despesasRows = $('Ler despesas').all().map(i => i.json).filter(r => r.id && r.valor);
const orcRows      = $('Ler orcamento').all().map(i => i.json).filter(r => r.descricao_custo && r.Valor_prev);
const rifaPRows    = $('Ler rifa_principal').all().map(i => i.json).filter(r => r.numero);

const cfg = {};
for (const r of configRows) cfg[r.chave] = r.valor;
const meta = Number(cfg.meta_total) || 40000;
const valorRifa = Number(cfg.valor_rifa) || 30;

const salesByAtleta = {};
for (const r of rifaPRows) {
  if (r.num_atleta) {
    const k = String(r.num_atleta);
    salesByAtleta[k] = (salesByAtleta[k] || 0) + 1;
  }
}

const atletas = atletasRows.map(r => ({
  num: String(r.Camisa).padStart(2, '0'),
  name: String(r.nome_completo || ''),
  short: String(r.short || ''),
  pos: String(r.pos || ''),
  photo: (r.photo && r.photo !== 'sem foto') ? '/Fotos_Atletas/' + r.photo : null,
  sales: salesByAtleta[String(r.Camisa)] || 0
}));

const rifasTotal   = rifasRows.reduce((s, r) => s + Number(r.total_arrecadado || 0), 0);
const cantinaTotal = cantinaRows.reduce((s, r) => s + Number(r.total_arrecadado || 0), 0);
const doacoesTotal = doacoesRows.reduce((s, r) => s + Number(r.valor || 0), 0);
const rifaPTotal   = rifaPRows.length * valorRifa;

const receitas = [
  { label: 'Rifa Principal', sub: rifaPRows.length + ' números vendidos', valor: rifaPTotal },
  { label: 'Rifas Avulsas', sub: rifasRows.length + ' rifas realizadas', valor: rifasTotal },
  { label: 'Cantina', sub: cantinaRows.length + ' evento(s)', valor: cantinaTotal },
  { label: 'Doações', sub: doacoesRows.length + ' doação(ões)', valor: doacoesTotal }
];

const orcamento = orcRows.map(r => ({
  label: String(r.descricao_custo),
  sub: '',
  valor: Number(r.Valor_prev)
}));

const extrato = [];
for (const r of rifasRows) {
  extrato.push({ data: toDate(r.data), desc: r.nome_rifa + ' · ' + (r.bilhetes_vendidos || 0) + ' bilhetes', cat: 'RIFA AVULSA', tipo: 'ENTRADA', valor: Number(r.total_arrecadado) });
}
for (const r of cantinaRows) {
  extrato.push({ data: toDate(r.data), desc: String(r.evento || 'Cantina'), cat: 'CANTINA', tipo: 'ENTRADA', valor: Number(r.total_arrecadado) });
}
for (const r of doacoesRows) {
  extrato.push({ data: toDate(r.data), desc: 'Doação · ' + (r.doador_nome || 'Anônimo'), cat: 'DOAÇÃO', tipo: 'ENTRADA', valor: Number(r.valor) });
}
for (const r of despesasRows) {
  extrato.push({ data: toDate(r.data), desc: String(r.descricao || r.categoria || 'Despesa'), cat: String(r.categoria || 'DESPESA').toUpperCase(), tipo: 'SAÍDA', valor: Number(r.valor) });
}

extrato.sort(function(a, b) {
  function p(s) {
    if (!s) return 0;
    const parts = s.split('/');
    return new Date(Number(parts[2]), Number(parts[1]) - 1, Number(parts[0])).getTime();
  }
  return p(b.data) - p(a.data);
});

const arrecadado = receitas.reduce((s, r) => s + r.valor, 0);
const gasto = despesasRows.reduce((s, r) => s + Number(r.valor || 0), 0);

return [{ json: { meta, arrecadado, gasto, atletas, receitas, orcamento, extrato } }];
